/**
 * ChatFilesys — 摘要文本清洗（**纯函数，零宿主依赖**，故可在 `node --test` 下直接测）
 *
 * ── 为什么必须有它（真机实测）──
 * 2026-09-28 用实例里配好的「类脑-GGg3.1p」（`gemini-3.1-pro-preview`）跑分支总结，
 * 提示词要求「只输出概括本身，不要引号、不要解释」，**拿回来的却是 `</think_nya~`**
 * ——思维链的闭合残片。推理型模型常把思考过程与正式回答一起吐出来
 * （`…` / `<thinking>…</thinking>`），有的还会吐出**不闭合**的半截标签。
 * 直接按长度截前 N 个字，用户看到的就是这种垃圾。
 *
 * ── 做法（只做能确定的事，不对模型行为做假设）──
 * 1. 去掉**成对**的思维块（`<think…>…</think…>` / `<thinking>…</thinking>`，大小写不敏感）
 * 2. 去掉**孤立**的思维标签本身
 * 3. 若剩下仍以 `<` 开头 ⇒ 说明还有一个没闭合的思维块，**丢掉第一个 `>` 之前的内容**
 * 4. 剥掉包裹的引号 / 书名号 / 方括号（提示词写了「不要引号」，但模型不一定听）
 * 5. 折叠空白
 *
 * **不做**的事：不猜「哪句才是真摘要」（没有可靠判据，猜错比不做更糟）、
 * 不按标点截断（会切坏句子）、不改写内容（那不是清洗）。
 */

/** 成对的思维块（含 `<thinking>` 变体；`[^>]*` 吃掉属性） */
const PAIRED = /<think(?:ing)?[^>]*>[\s\S]*?<\/think(?:ing)?[^>]*>/gi;
/** 孤立标签（不配对的半截） */
const LONE = /<\/?think(?:ing)?[^>]*>/gi;
/** 包裹符号（首尾都要剥；引号与中日文书名号/括号都算） */
const WRAP = /^[\s"'“”「」『』【】[\]（）()]+|[\s"'“”「」『』【】[\]（）()]+$/g;

/**
 * @param {unknown} raw 模型原始输出（任何类型都吃下，非字符串走 `String()`）
 * @returns {string} 清洗后的文本；**可能为空**——调用方据此报「生成结果为空」，
 *   不要在这里编一个默认值出来
 */
export function cleanSummaryText(raw) {
    let s = String(raw ?? '');
    s = s.replace(PAIRED, '');
    s = s.replace(LONE, '');
    // 2b) **半截的 think 标签**：`</think_nya~正文…` 这种（标签后跟着杂字符、且没有 `>`）。
    //     只针对 think 系标签做，**不用通用启发式**——通用规则会误伤正常文本。
    //     杂字符**限定为标签字符集**（`[A-Za-z0-9_-~]`）：用 `[^\s>]*` 会把后面的正文
    //     一起吃掉（CJK 也不是空白）——第一版就是这么写的，用例当场抓到（2026-09-28）。
    s = s.replace(/^\s*<\/?think(?:ing)?[A-Za-z0-9_~-]*/i, '');
    if (/^\s*</.test(s)) {
        const i = s.indexOf('>');
        // 走到这里说明开头仍是 `<`：有 `>` 就丢掉它之前；**没有 `>`** ⇒ 整串都是残片，全丢。
        // 保留它等于把残片当摘要交给用户——那比「生成结果为空」更糟。
        s = i >= 0 ? s.slice(i + 1) : '';
    }
    s = s.replace(WRAP, '');
    s = s.replace(/\s+/g, ' ').trim();
    // **宿主把 `undefined` 变成字符串交回来**：真机实测（Dev Luker 8003，2026-09-28），
    // `generateQuietPrompt` 返回的是字面量 `"undefined"`（它内部没真调用）。
    // 那不是摘要，是「没有答案」——按空处理，让调用方去试下一条链路 / 报「生成结果为空」。
    if (/^(undefined|null|nan)$/i.test(s)) return '';
    return s;
}
